/* Versioned reviewable draft order sets and transparent quality/financial metrics. */
state.orderDrafts??={};state.orderHistory??=[];state.quality??={};state.finance??=null;
TABS.push('Order set','Timing & quality');navs.push('Clinical quality','Financial impact');
assessmentFields.push(['Medication reference safeguards',[
 ['Renal function stable','Renal function stable / CrCl clinically verified','yesno'],['Dialysis','Dialysis / renal replacement therapy','yesno']
]]);
const orderSources={idsa:{label:'IDSA 2010 FN, recommendations 9–14, 21 / 28',url:'https://www.idsociety.org/practice-guideline/neutropenic-patients-with-cancer/'},outpatient:{label:'ASCO/IDSA 2018, recommendations 3–6',url:'https://www.idsociety.org/practice-guideline/fever-and-neutropenia-in-adults-with-cancer/'},cefepime:{label:'FDA cefepime label, revised 07/2025; sections 2.1 / 2.3',url:'https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/050817s012lbl.pdf'}};
const templates={
 'FN-1':{title:'Low-risk eligibility / outpatient review',items:['CBC with differential; renal and liver tests','Blood culture sampling plan before antibiotics without delaying therapy','Other microbiology / imaging guided by symptoms and clinical review','Document oral tolerance, prophylaxis and reliable follow-up','Observe and reassess before clinician disposition decision','Document follow-up, contact access and return precautions'],med:'Oral fluoroquinolone plus amoxicillin/clavulanate is a source-supported option for selected outpatients; prior quinolone prophylaxis, resistance, allergy and eligibility require review. No automatic dose supplied.',source:'outpatient'},
 'FN-2':{title:'High-risk inpatient review',items:['Admission and current haemodynamic assessment','CBC with differential; renal/liver tests; lactate when clinically indicated','Blood culture collection plan; do not delay first empirical therapy','Review antipseudomonal IV beta-lactam options against local resistance','Review allergy, renal function and additional infection-specific coverage','Document monitoring and reassessment plan'],med:'Potential IV options in IDSA include cefepime, piperacillin/tazobactam or a carbapenem; no option is automatically selected.',source:'idsa'},
 'FN-3':{title:'Instability / urgent specialist assessment',items:['Immediate clinician assessment of current instability','Activate approved local sepsis / rapid-response pathway if indicated','Review perfusion, lactate and organ function in context','Urgent oncology / ID and ICU assessment as indicated','Individualize empirical antimicrobials to source, resistance and organ function','Document reassessment and escalation ownership'],med:'No fixed carbapenem, aminoglycoside or fluid order is generated. High MASCC risk or lactate alone does not diagnose shock.',source:'idsa'},
 'FN-4':{title:'Suspected catheter infection add-on',items:['Record line type, site findings and suspected source','Review paired peripheral / catheter culture sampling','Assess indications for additional Gram-positive coverage','Document ID / line-management review and source-control plan'],med:'Additional coverage and line management require clinical/microbiological assessment; no automatic vancomycin dose.',source:'idsa'},
 'FN-5':{title:'Resistant-organism risk add-on',items:['Confirm MRSA / ESBL / CRE history and prior susceptibility results','Review recent antibiotic exposure and local antibiogram','Request ID / microbiology input for targeted empirical strategy','Reassess when organism identification / susceptibilities arrive'],med:'Different resistant organisms require different strategies; no universal carbapenem selection, especially for CRE.',source:'idsa'},
 'FN-6':{title:'Persistent-fever / fungal evaluation add-on',items:['Confirm fever course and adequate antibacterial therapy duration','Review anticipated neutropenia duration and prior antifungal prophylaxis','Review repeat cultures, imaging and fungal investigations as indicated','ID assessment of empirical versus pre-emptive antifungal strategy','Document ongoing reassessment and escalation'],med:'Persistent fever prompts contextual specialist review; it is not an automatic antifungal prescription.',source:'idsa'}
};
function orderContext(pid){const p=patients.find(x=>id(x)===pid),a=state.allergies[pid]||{};return JSON.stringify({p,allergy:a,results:latestResults(pid).map(r=>[r.eventId,r.status,r.value])})}
function orderView(){const pid=id(selected),o=state.orderDrafts[pid],x=draftPathways(selected);return `<section class="panel"><div class="sectiontitle"><div><h2>Reviewable order set</h2><p>Source-linked draft · no prescription signing or transmission</p></div><button class="btn" onclick="exportOrder()" ${!o?'disabled':''}>Export draft</button></div><div class="notice">These are editable clinical review drafts, not executable orders. Drug doses outside the limited cefepime label reference require independent verification.</div><div class="tools"><select id="orderTemplate" aria-label="Order set template"><option value="" disabled ${!o?'selected':''}>Select a draft template</option>${Object.entries(templates).map(([k,t])=>`<option value="${k}" ${o?.subtype===k?'selected':''}>${k} · ${t.title}</option>`).join('')}</select><button class="btn primary" onclick="generateOrder()">${o?'Create new version':'Generate draft'}</button></div><p>Candidate modules: ${esc(x.matches.map(m=>m.code).join(', ')||'not established')}. Select the clinical draft deliberately; overlapping modules remain relevant.</p>${o?`<span class="pill ${o.review&&o.context===orderContext(pid)?'':'amber'}">${o.review&&o.context===orderContext(pid)?'Reviewed demo draft':'Draft / review required'}</span><p>Version ${o.version} · ${esc(o.subtype)} · ${fmt(o.createdAt)} ${o.context!==orderContext(pid)?'· patient/result context changed — previous review invalid':''}</p><div class="scroll"><table><thead><tr><th>Include</th><th>Proposed review item</th><th>Action</th></tr></thead><tbody>${o.items.map((r,i)=>`<tr><td><input aria-label="Include order item ${i+1}" type="checkbox" ${r.include?'checked':''} onchange="toggleOrderItem(${i},this.checked)"></td><td>${esc(r.text)}</td><td><button class="btn" onclick="editOrderItem(${i})">Edit</button></td></tr>`).join('')}</tbody></table></div><h3>Medication review</h3><p>${esc(templates[o.subtype].med)}</p><p><a href="${orderSources[templates[o.subtype].source].url}" target="_blank" rel="noopener">${orderSources[templates[o.subtype].source].label}</a></p><div class="actions"><button class="btn" onclick="editOrderItem(-1)">Add item</button><button class="btn primary" onclick="reviewOrder()">Review draft</button><button class="btn" onclick="window.print()">Print draft</button><button class="btn" onclick="showOrderHistory()">Version history</button></div>`:''}<details><summary>Cefepime dose / renal label reference · limited scope</summary>${cefepimeCard(selected)}</details></section>`}
function cefepimeCard(p){const r=cefepimeReference(p['CrCl (mL/min)'],p['Renal function stable'],p.Dialysis,state.allergies[id(p)]?.status);return `<p><a href="${orderSources.cefepime.url}" target="_blank" rel="noopener">${orderSources.cefepime.label}</a></p>${r.blocked?`<div class="notice">Reference withheld: ${esc(r.reason)}</div><button class="btn" onclick="openAssessment(false)">Review renal inputs</button><button class="btn" onclick="openAllergy()">Review allergy</button>`:`<p>${esc(r.initial)}<br>Maintenance for the FN label regimen at recorded CrCl: <b>${esc(r.maintenance)}</b></p><p>${esc(r.note)}</p>`}<p>Drug selection still requires infection-specific assessment. This is the FDA label table, not local formulary approval, and does not authorize an order.</p>`}
function generateOrder(){const pid=id(selected),k=document.querySelector('#orderTemplate').value;if(!templates[k]){openDialog('Choose a review template','<p>Select a template after reviewing the candidate modules. No low-risk template is selected by default.</p><button class="btn" onclick="closeDialog()">Back</button>');return}const prev=state.orderDrafts[pid];if(prev)state.orderHistory.unshift({patientId:pid,...JSON.parse(JSON.stringify(prev))});state.orderDrafts[pid]={subtype:k,version:(prev?.version||0)+1,createdAt:new Date().toISOString(),context:orderContext(pid),items:templates[k].items.map(text=>({text,include:true})),review:null};save('Generated draft order set '+k+' v'+state.orderDrafts[pid].version,pid)}
function preserveOrderVersion(){const pid=id(selected),o=state.orderDrafts[pid];state.orderHistory.unshift({patientId:pid,...JSON.parse(JSON.stringify(o))});o.version++;o.review=null;o.createdAt=new Date().toISOString();o.context=orderContext(pid);return o}
function toggleOrderItem(i,on){const o=preserveOrderVersion();o.items[i].include=on;save('Changed draft order inclusion; review invalidated',id(selected))}
function editOrderItem(i){const o=state.orderDrafts[id(selected)];if(!o)return;openDialog(i<0?'Add draft item':'Edit draft item',`<form onsubmit="event.preventDefault();saveOrderItem(${i},this)"><label class="field">Proposed item<textarea name="text" required maxlength="600">${esc(i<0?'':o.items[i].text)}</textarea></label><button class="btn primary" type="submit">Save new draft version</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
function saveOrderItem(i,form){const text=String(new FormData(form).get('text')||'').trim();if(!text)return;const o=preserveOrderVersion();if(i<0)o.items.push({text,include:true});else o.items[i].text=text;closeDialog();save('Edited order draft; review invalidated',id(selected))}
function reviewOrder(){openDialog('Review demo order draft',`<p>This records a demo reviewer label, not an authenticated clinical signature. Included medication orders still require verified dose, route, timing and clinician authorization.</p><form onsubmit="event.preventDefault();saveOrderReview(this)"><label class="field">Reviewer label<input name="reviewer" required maxlength="120"></label><label class="field">Review / changes / outstanding limitations<textarea name="note" required maxlength="600"></textarea></label><button class="btn primary" type="submit">Record demo review</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
function saveOrderReview(form){const f=new FormData(form),o=state.orderDrafts[id(selected)];const reviewer=String(f.get('reviewer')||'').trim(),note=String(f.get('note')||'').trim();if(!o||!reviewer||!note)return;o.context=orderContext(id(selected));o.review={reviewer,note,time:new Date().toISOString()};closeDialog();save('Recorded demo review of order draft v'+o.version,id(selected))}
function exportOrder(){const o=state.orderDrafts[id(selected)];if(!o)return;download(id(selected)+'-DRAFT-orders.json',{status:'NOT_EXECUTABLE_NOT_SIGNED',patient:id(selected),...o,context:undefined,contextChanged:o.context!==orderContext(id(selected)),sources:orderSources});save('Exported draft order set (not transmitted)',id(selected))}
function showOrderHistory(){const h=state.orderHistory.filter(o=>o.patientId===id(selected));openDialog('Previous draft versions',h.map(o=>`<div class="stage">v${o.version} · ${esc(o.subtype)} · ${fmt(o.createdAt)}<p>${o.items.filter(i=>i.include).length} included items; ${o.review?'demo-reviewed':'unreviewed'}</p></div>`).join('')||'<p>No previous versions.</p>')}
function seedQuality(){if(state.qualitySeedVersion===1)return;for(const pid of ['WALK-LOW-01','WALK-HIGH-01']){if(state.quality[pid])continue;const c=careFor(pid);state.quality[pid]={cancerHistory:'Yes',alreadyTreated:'No',transferredTreated:'No',comfortOnly:'No',triageAt:c.steps.triage?.time||null,firstAppropriateAt:c.treatment?.administeredAt||null,regimen:c.treatment?.regimen||'',appropriate:'Yes',reviewer:'Synthetic scenario reviewer',reviewNote:'Fictional appropriateness assumption for metric demonstration only; not a real pharmacist review.',masccDocumented:'Yes',outcome:'Not measured',readmission:'Unknown',savedAt:new Date().toISOString()}}state.qualitySeedVersion=1;try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{}}
seedQuality();
function metricFor(p){return episodeMetric(p,state.quality[id(p)],fnEligibility(p).status)}
function ynSelect(name,label,value){return `<label class="field">${label}<select name="${name}"><option value="">Unknown / unreviewed</option>${['Yes','No'].map(x=>`<option ${value===x?'selected':''}>${x}</option>`).join('')}</select></label>`}
function timingView(){const p=selected,q=state.quality[id(p)]||{},m=metricFor(p);return `<section class="panel"><div class="sectiontitle"><div><h2>Timing, exclusions & appropriateness</h2><p>Encounter-level metric documentation; one current episode per synthetic patient.</p></div><button class="btn" onclick="go('Clinical quality')">Quality dashboard →</button></div><div class="banner">${esc(m.group)} · ${esc(m.outcome||m.reason)} ${m.minutes!==undefined?'· '+m.minutes.toFixed(1)+' minutes':''}. Timeliness and appropriate selection are process measures, not proof of treatment effectiveness.</div><form onsubmit="event.preventDefault();saveQuality(this)"><div class="grid2">${ynSelect('cancerHistory','Cancer / chemotherapy history confirmed',q.cancerHistory)}${ynSelect('alreadyTreated','Appropriate therapy already given before arrival',q.alreadyTreated)}${ynSelect('transferredTreated','Transferred after antibiotics elsewhere',q.transferredTreated)}${ynSelect('comfortOnly','Comfort-care / palliative-only care plan',q.comfortOnly)}</div><p>Palliative anticancer treatment intent alone is not the same as comfort-care-only and does not automatically exclude this episode.</p><div class="grid2"><label class="field">Triage time<input name="triageAt" type="datetime-local" value="${localInput(q.triageAt)}"></label><label class="field">Actual first appropriate antipseudomonal dose time<input name="firstAppropriateAt" type="datetime-local" value="${localInput(q.firstAppropriateAt)}"></label></div><label class="field">Regimen associated with that dose<input name="regimen" maxlength="180" value="${esc(q.regimen||'')}"></label>${ynSelect('appropriate','Clinician judges this regimen appropriate for the episode',q.appropriate)}<div class="grid2"><label class="field">Appropriateness reviewer label<input name="reviewer" maxlength="120" value="${esc(q.reviewer||'')}"></label><label class="field">Reason / evidence and clinical context<textarea name="reviewNote" maxlength="800">${esc(q.reviewNote||'')}</textarea></label></div>${ynSelect('masccDocumented','MASCC reviewed and documented for this episode',q.masccDocumented)}<h3>Clinical response — separate from process compliance</h3><div class="grid2"><label class="field">Recorded response at reassessment<select name="outcome">${['Not measured','Improved (clinician recorded)','Unchanged','Deteriorated'].map(x=>`<option ${q.outcome===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Unplanned readmission recorded<select name="readmission">${['Unknown','Yes','No'].map(x=>`<option ${q.readmission===x?'selected':''}>${x}</option>`).join('')}</select></label></div><p>No fixed response time window is implied. Readmission rates require a defined follow-up period before interpretation.</p><p id="qualityError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save metric review</button><button class="btn" type="button" onclick="openAssessment(false)">Complete FN criteria</button></div></form></section>`}
function saveQuality(form){try{const f=new FormData(form),q={};for(const k of ['cancerHistory','alreadyTreated','transferredTreated','comfortOnly','appropriate','regimen','reviewer','reviewNote','masccDocumented','outcome','readmission'])q[k]=String(f.get(k)||'').trim();for(const k of ['triageAt','firstAppropriateAt'])q[k]=f.get(k)?new Date(String(f.get(k))).toISOString():null;if(q.triageAt&&q.firstAppropriateAt&&q.firstAppropriateAt<q.triageAt)throw Error('Actual administration cannot precede triage.');if(q.appropriate==='Yes'&&(!q.regimen||!q.reviewer||!q.reviewNote))throw Error('Appropriateness requires regimen, reviewer and rationale.');q.savedAt=new Date().toISOString();state.quality[id(selected)]=q;save('Updated encounter timing, exclusions and appropriateness review',id(selected))}catch(e){document.querySelector('#qualityError').textContent=e.message}}
function clinicalQualityView(){const rows=patients.map(p=>({patientId:id(p),name:patientName(p),...metricFor(p)})),s=summarizeEpisodes(rows),eligible=patients.filter(p=>metricFor(p).group==='denominator'),mascc=eligible.filter(p=>state.quality[id(p)]?.masccDocumented==='Yes').length,orderUsed=eligible.filter(p=>state.orderDrafts[id(p)]).length,concordant=eligible.filter(p=>state.quality[id(p)]?.appropriate==='Yes'&&state.quality[id(p)]?.reviewer&&state.quality[id(p)]?.reviewNote&&state.quality[id(p)]?.regimen).length;return header('Clinical quality','Transparent numerators, denominators, exclusions and unknowns.',`<button class="btn" onclick="download('fn-quality-report.json',{synthetic:true,summary:s,episodes:rows})">Export report</button>`)+`<div class="banner">Synthetic current-episode data only. No hospital baseline, comparative improvement or clinical efficacy is claimed. Do not treat unknown eligibility as a successful case or a known exclusion.</div><div class="cards"><div class="card"><small>APPROPRIATE DOSE ≤60 MIN</small><b class="number">${s.rate===null?'—':s.rate.toFixed(1)+'%'}</b><p>${s.numerator} / ${s.denominator} established eligible episodes</p></div><div class="card"><small>ELIGIBILITY UNKNOWN</small><b class="number">${s.unknown}</b><p>Separate unresolved population; not silently excluded</p></div><div class="card"><small>DOCUMENTED EXCLUSIONS</small><b class="number">${s.excluded}</b><p>${s.notEligible} other non-eligible episodes</p></div><div class="card"><small>ELIGIBLE WITH DATA GAPS</small><b class="number">${s.missing}</b><p>Remain in denominator; not credited as compliant</p></div></div><section class="panel"><h2>Secondary process indicators</h2><p>MASCC documentation: ${mascc}/${s.denominator} · draft order-set use: ${orderUsed}/${s.denominator} · clinician-recorded regimen appropriateness: ${concordant}/${s.denominator}.</p><p>Order-set use means a draft was generated, not signed or administered. Appropriateness is manual clinical review, not an automated validated concordance engine. Form completion time: not yet instrumented.</p><details><summary>Metric specification</summary><p>Numerator: established eligible adult FN episodes with documented first appropriate antipseudomonal administration ≤60 minutes after triage, including reviewer/rationale. Denominator: adult cancer/chemotherapy-history FN episodes after reviewed exclusions. Exclusions: appropriate pre-arrival treatment, transfer after antibiotics, comfort-care-only, age under 18. Eligible episodes with missing times/review remain in denominator. Episodes with unresolved eligibility/exclusion review are reported separately, so this is a reviewed-cohort rate, not a whole-hospital rate.</p><p>Source: ASCO/IDSA 2018 and supplied capstone specification. Data are episode-level snapshots without case-mix adjustment.</p></details></section><section class="panel" style="margin-top:20px"><h2>Episode audit</h2><div class="scroll"><table><thead><tr><th>Patient</th><th>Eligibility</th><th>Result / gap</th><th>Action</th></tr></thead><tbody>${rows.filter(r=>r.patientId.startsWith('WALK-')||r.group==='denominator').slice(0,40).map(r=>`<tr><td>${esc(r.name)}<div class="mini">${r.patientId}</div></td><td>${esc(r.group)}</td><td>${esc(r.outcome||r.reason)} ${r.minutes!==undefined?'· '+r.minutes.toFixed(1)+' min':''}</td><td><button class="btn" onclick="openPatient('${r.patientId}');changeTab('Timing & quality')">Review</button></td></tr>`).join('')}</tbody></table></div></section>`}
function financialView(){let f=state.finance,m=null;try{if(f)m=financeMetrics(f)}catch{}const pct=v=>v===null?'—':v.toFixed(1)+'%',money=v=>Number(v).toLocaleString(undefined,{maximumFractionDigits:2});return header('Claims & revenue impact','Separate rejection reduction, revenue change and proof of attribution.',`<button class="btn" onclick="editFinance()">Enter financial values</button>`)+`<div class="notice">No claims or revenue values were found in the supplied clinical cohort. Financial inputs are independent; demo examples are labelled and do not establish that the CDS caused any change.</div>${m?`<span class="pill ${f.origin==='Illustrative example'?'amber':''}">${esc(f.origin)} · ${esc(f.currency)} · ${esc(f.basePeriod)} → ${esc(f.postPeriod)}</span><div class="cards" style="margin-top:20px"><div class="card"><small>CLAIM REJECTION RATE</small><b class="number">${pct(m.baseRate)} → ${pct(m.postRate)}</b><p>Rejected / submitted claims in each period</p></div><div class="card"><small>REDUCTION</small><b class="number">${m.percentagePointReduction===null?'—':m.percentagePointReduction.toFixed(1)+' pp'}</b><p>Relative reduction: ${pct(m.relativeReduction)}</p></div><div class="card"><small>REVENUE CHANGE</small><b class="number">${money(m.revenueChange)}</b><p>${pct(m.revenueGrowth)} observed growth · ${esc(f.currency)}</p></div><div class="card"><small>REJECTED VALUE REDUCTION</small><b class="number">${money(m.rejectedValueChange)}</b><p>Not recovered cash; do not add to revenue change</p></div></div><section class="panel"><h2>Interpretation & improvement items</h2><p>Observed rejection-rate reduction is calculated as baseline rate minus follow-up rate; negative values indicate worsening. Relative reduction divides that change by baseline rate. Revenue growth compares entered revenue totals and may reflect volume, prices, payer mix or other changes.</p><p>Potential improvement actions: document medical necessity, reconcile diagnoses/procedures and actual administration, complete records before billing, review payer-specific rejection reasons and monitor resubmission outcomes. These are proposed process actions, not measured CDS effects.</p><p>Data source / note: ${esc(f.note||'Not provided')}. Periods must be comparable, definitions consistent, currency identical and revenue measured on the same basis (for example collected cash). No causal or ROI claim is generated.</p><button class="btn" onclick="download('fn-financial-comparison.json',{inputs:state.finance,metrics:financeMetrics(state.finance),causalAttribution:'not established'})">Export financial comparison</button></section>`:`<section class="panel"><h2>Financial values not entered</h2><p>Enter your actual baseline and follow-up values, or load a clearly marked example to test the calculations.</p><button class="btn primary" onclick="editFinance()">Enter values</button><button class="btn" onclick="loadFinanceExample()">Load illustrative example</button></section>`}`}
function editFinance(){const f=state.finance||{};const fields=[['baseClaims','Submitted claims · baseline'],['postClaims','Submitted claims · follow-up'],['baseRejected','Rejected claims · baseline'],['postRejected','Rejected claims · follow-up'],['baseRevenue','Revenue on consistent basis · baseline'],['postRevenue','Revenue on consistent basis · follow-up'],['baseRejectedValue','Rejected claim value · baseline'],['postRejectedValue','Rejected claim value · follow-up']];openDialog('Financial comparison inputs',`<form onsubmit="event.preventDefault();saveFinance(this)"><div class="grid2"><label class="field">Baseline period<input name="basePeriod" value="${esc(f.basePeriod||'')}" required maxlength="80"></label><label class="field">Follow-up period<input name="postPeriod" value="${esc(f.postPeriod||'')}" required maxlength="80"></label><label class="field">Currency<input name="currency" value="${esc(f.currency||'EGP')}" required maxlength="10"></label><label class="field">Data origin<select name="origin">${['User-entered actual aggregate','Illustrative example'].map(x=>`<option ${f.origin===x?'selected':''}>${x}</option>`).join('')}</select></label>${fields.map(([k,l])=>`<label class="field">${l}<input type="number" name="${k}" min="0" step="${k.includes('Claims')||k.includes('Rejected')&&!k.includes('Value')?'1':'any'}" value="${f[k]??''}" required></label>`).join('')}</div><label class="field">Source / rejection definition / revenue basis<textarea name="note" required maxlength="800">${esc(f.note||'')}</textarea></label><p id="financeError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save & calculate</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#workflowDialog').classList.add('assessmentdialog')}
function saveFinance(form){try{const raw=Object.fromEntries(new FormData(form)),f={};for(const k of ['baseClaims','postClaims','baseRejected','postRejected','baseRevenue','postRevenue','baseRejectedValue','postRejectedValue']){if(raw[k]==='')throw Error('Complete all values');f[k]=Number(raw[k]);if(['baseClaims','postClaims','baseRejected','postRejected'].includes(k)&&!Number.isInteger(f[k]))throw Error('Claim counts must be integers.')}for(const k of ['basePeriod','postPeriod','currency','origin','note'])f[k]=String(raw[k]||'').trim();if(!f.note||!f.basePeriod||!f.postPeriod||!f.currency)throw Error('Record periods, currency and data-source note.');financeMetrics(f);state.finance=f;closeDialog();save('Updated financial comparison; source '+f.origin+'; causal effect not established')}catch(e){document.querySelector('#financeError').textContent=e.message}}
function loadFinanceExample(){state.finance={origin:'Illustrative example',currency:'EGP',basePeriod:'Example month A',postPeriod:'Example month B',baseClaims:1000,postClaims:1000,baseRejected:150,postRejected:90,baseRevenue:1000000,postRevenue:1080000,baseRejectedValue:150000,postRejectedValue:90000,note:'Invented equal-duration example only. Revenue values assumed collected cash; not actual user data or attributable CDS impact.'};save('Loaded explicitly illustrative financial example')}
const detailBeforeOrders=detail;detail=function(){let h=detailBeforeOrders();if(selected&&patientTab==='Order set')h+=orderView();if(selected&&patientTab==='Timing & quality')h+=timingView();return h};
const renderBeforeOrders=render;render=function(){renderBeforeOrders();if(view==='Clinical quality')$('#app').innerHTML=clinicalQualityView();if(view==='Financial impact')$('#app').innerHTML=financialView()};
for(const row of scopeCoverage){if(row[0]==='Ready-to-sign order sets'){row[1]='Reviewable draft implemented';row[2]='Six source-linked editable/versioned draft templates; demo review/export. Not executable or authenticated signatures.'}if(row[0]==='Medication doses / renal adjustment'){row[1]='Limited source reference';row[2]='Cefepime FDA 07/2025 initial/maintenance renal reference gated by allergy, stable renal function and no dialysis. Other medication dosing remains independently verified.'}if(row[0]==='First appropriate antibiotic within 60 min'){row[1]='Reviewed-cohort metric implemented';row[2]='Timing, exclusions, manual appropriateness and explicit unknown population. Not a whole-hospital or efficacy measure.'}if(row[0]==='Secondary metrics'){row[1]='Partial process indicators';row[2]='MASCC documentation, generated-draft use and manual appropriateness. Saved-form wall-clock timing collected; validated automated concordance remains pending.'}}
state.formTimes??=[];
let assessmentStartedAt=null;
const openAssessmentBeforeTimer=openAssessment;openAssessment=function(isNew){assessmentStartedAt=Date.now();openAssessmentBeforeTimer(isNew)};
const saveAssessmentBeforeTimer=saveAssessment;saveAssessment=function(form,isNew){const prior=state.assessmentHistory.length;saveAssessmentBeforeTimer(form,isNew);if(state.assessmentHistory.length>prior&&assessmentStartedAt!==null){const seconds=(Date.now()-assessmentStartedAt)/1000;state.formTimes.push({patientId:id(selected),seconds,recordedAt:new Date().toISOString()});assessmentStartedAt=null;save('Recorded assessment form wall-clock duration '+seconds.toFixed(1)+' sec (may include pauses)',id(selected))}};
const qualityBeforeTiming=clinicalQualityView;clinicalQualityView=function(){let h=qualityBeforeTiming();const times=state.formTimes.map(x=>x.seconds).filter(Number.isFinite).sort((a,b)=>a-b),median=times.length?(times[Math.floor((times.length-1)/2)]+times[Math.ceil((times.length-1)/2)])/2:null;return h.replace('Form completion time: not yet instrumented.',`Saved-form wall-clock duration: ${median===null?'no saved timings yet':median.toFixed(1)+' seconds median over '+times.length+' saves'}. Includes pauses; not active work time or a validated usability benchmark.`)};
